<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {post} from './api'
const model=defineModel<string>({default:''}),busy=ref(false),error=ref(''),presets=ref<any[]>([])
onMounted(async()=>{try{const r=await fetch('/presets/catalog.json');if(r.ok)presets.value=(await r.json()).filter((x:any)=>x.kind==='image')}catch{}})
async function choose(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;error.value='';if(!/\.(png|jpe?g|webp)$/i.test(file.name)||file.size>20*1024*1024){error.value='请选择不超过 20 MB 的 PNG、JPG 或 WebP 图片。';input.value='';return}await bind(file);input.value=''}
async function bind(file:File){busy.value=true;error.value='';try{const contentBase64=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]!);reader.onerror=reject;reader.readAsDataURL(file)});const uploaded=await post<any>('/v1/uploads',{filename:file.name,kind:'image',contentBase64});model.value=uploaded.path}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function choosePreset(item:any){try{const response=await fetch(item.url);if(!response.ok)throw Error('素材读取失败');await bind(new File([await response.blob()],item.filename))}catch(e){error.value=(e as Error).message}}
</script>
<template><section class="teacher-photo"><h3>教师参考图（可选）</h3><p>未上传时使用默认教师形象，不影响所选音色。</p><div v-if="presets.length" class="preset-photo-grid"><article v-for="item in presets" :key="item.id"><a :href="item.url" target="_blank" rel="noreferrer"><img :src="item.url" :alt="item.name"/></a><strong>{{item.name}}</strong><div><a :href="item.url" download>下载素材</a><el-button link type="primary" :disabled="busy" @click="choosePreset(item)">使用此素材</el-button></div></article></div><input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="choose"/><p v-if="busy">正在上传教师图片…</p><div v-if="model"><img class="selected-photo" :src="model" alt="当前教师参考图"/><el-button link @click="model=''">使用默认形象</el-button></div><el-alert v-if="error" :title="error" type="warning" :closable="false"/></section></template>
<style scoped>.teacher-photo{margin:24px 0}.teacher-photo p{color:#64776b;font-size:13px}.preset-photo-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:12px 0}.preset-photo-grid article{padding:9px;border:1px solid #dfe8e2;border-radius:9px;background:#f7faf8}.preset-photo-grid img{display:block;width:100%;height:120px;object-fit:cover;border-radius:6px}.preset-photo-grid strong{display:block;margin:7px 0;font-size:12px}.preset-photo-grid a{font-size:12px;color:#276447;margin-right:8px}.selected-photo{display:block;max-height:180px;max-width:100%;margin:12px 0}@media(max-width:700px){.preset-photo-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
